CREATE OR REPLACE FUNCTION migproto_split_note_sync() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE p int;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.note IS NOT NULL AND NEW.note_title IS NULL AND NEW.note_body IS NULL THEN
            p := position(': ' in NEW.note);
            IF p = 0 THEN NEW.note_title := NULL; NEW.note_body := NEW.note;
            ELSE NEW.note_title := substr(NEW.note, 1, p - 1); NEW.note_body := substr(NEW.note, p + 2); END IF;
        ELSIF NEW.note IS NULL AND (NEW.note_title IS NOT NULL OR NEW.note_body IS NOT NULL) THEN
            NEW.note := CASE WHEN NEW.note_title IS NULL THEN NEW.note_body ELSE NEW.note_title || ': ' || coalesce(NEW.note_body, '') END;
        END IF;
    ELSIF NEW.note IS DISTINCT FROM OLD.note THEN
        IF NEW.note IS NULL THEN NEW.note_title := NULL; NEW.note_body := NULL;
        ELSE
            p := position(': ' in NEW.note);
            IF p = 0 THEN NEW.note_title := NULL; NEW.note_body := NEW.note;
            ELSE NEW.note_title := substr(NEW.note, 1, p - 1); NEW.note_body := substr(NEW.note, p + 2); END IF;
        END IF;
    ELSIF NEW.note_title IS DISTINCT FROM OLD.note_title OR NEW.note_body IS DISTINCT FROM OLD.note_body THEN
        NEW.note := CASE WHEN NEW.note_title IS NULL THEN NEW.note_body ELSE NEW.note_title || ': ' || coalesce(NEW.note_body, '') END;
    END IF;
    RETURN NEW;
END;
$$
